CREATE OR REPLACE VIEW `Valid_Img` AS select `b`.`pro_id` AS `pro_id`,`a`.`img_id` AS `img_id`,`a`.`product_id` AS `product_id`,NULL AS `language_id`,`i`.`path` AS `images`,`a`.`created` AS `created`,`a`.`updated` AS `updated`,NULL AS `Img`,`i`.`path` AS `sImgURL`,`i`.`path` AS `ImgURL`,NULL AS `id_kor`,`i`.`original_name` AS `Description`,`b`.`company_id` AS `company_id`,`b`.`sku` AS `sku`,`b`.`default_image_id` = `a`.`image_id` AS `img_default` from ((`product_images` `a` left join `products` `b` on(`b`.`pro_id` = `a`.`product_id`)) left join `images` `i` on(`i`.`uuid` = `a`.`image_id`)) where `a`.`deleted_at` is null;
